package main
type Getter interface { Get() int }
type A int
type B int
func (a A) Get() int { return int(a)+1 }
func (b B) Get() int { return int(b)*2 }
func callA() int { var g Getter=A(2); return Getter.Get(g)+g.Get() }
func callB() int { var g Getter=B(3); return Getter.Get(g)+g.Get() }
func bound() int { x:=A(3); p:=&x; f:=p.Get; x=8; return f()+x.Get() }
func assertA() int { var x any=A(4); n, ok:=x.(A); if !ok { n=A(0) }; return int(n) }
func assertB() int { var x any=B(4); n, ok:=x.(A); if !ok { n+=3 }; return int(n) }
func incomparable() bool { var a any=[]int{2}; var b any=[]int{2}; return a==b }
func typedNil() bool { var x any=(*int)(nil); return x==nil }
